pub fn bash_fold_target_model_for_row(row: Rc<Node>, source_literal: std::string::String, source_text: String, production_binding: std::string::String, rule_name: std::string::String) -> Rc<Witness<Rc<TargetModel>>> {
    Rc::new(Witness::<Rc<TargetModel>>::Holds {
    value: crate::v2_std_compilers_target_model::target_model_make_with_emit_transforms(crate::v2_extdeps_languages_bash::bash_target_model_bundle(bash_fold_translation_rules_node_for_row(row, rule_name)), bash_fold_lex_carried(), bash_fold_binding_spellings_carried(), bash_fold_emit_transforms_carried(), source_text, target_emit_host_runtime_row_unconfigured()),
})
}

pub fn bash_fold_target_model_for_emitted_witness(emitted: Rc<Node>, source_literal: std::string::String, source_text: String, production_binding: std::string::String, rule_name: std::string::String) -> Rc<Witness<Rc<TargetModel>>> {
    match (*bash_fold_relation_row_witness(emitted, production_binding.clone())).clone() {
    Witness::Holds { value: row, .. } => bash_fold_target_model_for_row(row.clone(), source_literal, source_text, production_binding.clone(), rule_name),
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<TargetModel>>::Violates {
    diagnostic: d.clone(),
}),
}
}

